const {vec} = NMath;
const {vertices} = await IO.loadMesh("/assets/bunny.obj");

let pts = vertices.map(vertex => vec(...vertex));
const normalizeVectors = vectors => {
    const mean = vectors.reduce((sum, value) => sum.add(value), vec.zero(3)).scale(1 / vectors.length);
    const centered = vectors.map(value => value.sub(mean));
    const max = centered.reduce((largest, value) => Math.max(largest, value.map(Math.abs).fold(0, (a, x) => Math.max(a, x))), 0);
    const scaled = max === 0 ? centered : centered.map(value => value.scale(1 / max));
    return scaled.map(({components: [x, y, z]}) => vec(z, x, y));
};
pts = normalizeVectors(pts);

const graph = Graph.knn(pts, 8, (x, y) => x.sub(y).length());
const normalLength = 0.05;

// the normal is the eigenvector with the lowest eigenvalue of the neighborhood covariance
const estimateNormal = id => {
    const neighborhood = [id, ...graph.getNeighbors(id)].map(j => graph.getVertex(j).vertex.toArray());
    const {components} = PCA.new(neighborhood, 3);
    return components[components.length - 1];
};

const lines = graph.getVertices().map(({id, vertex}) => {
    const normal = estimateNormal(id);
    return [vertex.toArray(), vertex.add(normal.scale(normalLength)).toArray()];
});

IO.plotLineCloud(lines, {color: [1, 0, 0]});
